"use client";

import Link from "next/link";
import { FormEvent, useState } from "react";
import { useParams } from "next/navigation";
import { ApiError, grantConsent, type ConsentGrantOut } from "@/lib/api";
import {
  ApiErrorAlert,
  fieldErrorMap,
} from "@/components/forms/ApiErrorAlert";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
} from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

export default function ConsentGrantPage() {
  const params = useParams<{ token: string }>();
  const token = decodeURIComponent(params.token);

  const [participation, setParticipation] = useState(false);
  const [publicDisplay, setPublicDisplay] = useState(false);
  const [grantedBy, setGrantedBy] = useState("");
  const [result, setResult] = useState<ConsentGrantOut | null>(null);
  const [error, setError] = useState<ApiError | null>(null);
  const [pending, setPending] = useState(false);

  async function onSubmit(e: FormEvent) {
    e.preventDefault();
    setError(null);
    setPending(true);
    try {
      const scopes: string[] = [];
      if (participation) scopes.push("participation");
      if (publicDisplay) scopes.push("public");
      const out = await grantConsent(token, {
        scopes,
        grantedBy: grantedBy.trim() || null,
      });
      setResult(out);
    } catch (err) {
      if (err instanceof ApiError) {
        setError(err);
        fieldErrorMap(err.fields);
      } else {
        setError(
          new ApiError(0, {
            error: {
              code: "HTTP_ERROR",
              message: "Could not grant consent",
              fields: [],
              traceId: "",
            },
          }),
        );
      }
    } finally {
      setPending(false);
    }
  }

  const participationGranted =
    result?.scopesGranted.includes("participation") ?? false;
  const publicGranted = result?.scopesGranted.includes("public") ?? false;

  return (
    <div className="mx-auto max-w-xl space-y-6 px-4 py-8 sm:px-6 sm:py-10">
      <Button variant="link" className="h-auto min-h-11 px-0" asChild>
        <Link href="/">← Home</Link>
      </Button>

      <Card>
        <CardHeader className="px-4 sm:px-6">
          <h1 className="text-2xl font-semibold tracking-tight">
            Grant guardian consent
          </h1>
          <CardDescription>
            Participation consent unlocks progression. Public display is
            optional and withheld unless you select it.
          </CardDescription>
        </CardHeader>
        <CardContent className="px-4 sm:px-6">
          {result ? (
            <div className="space-y-4" data-testid="consent-grant-success">
              <Alert role="status">
                <AlertTitle>Consent recorded</AlertTitle>
                <AlertDescription>
                  Status: {result.status}.
                  {participationGranted
                    ? " Participation unlock is active."
                    : " Participation consent was not selected."}
                </AlertDescription>
              </Alert>
              <div className="flex flex-wrap gap-2">
                <Badge
                  data-testid="granted-participation"
                  data-granted={participationGranted ? "true" : "false"}
                  variant={participationGranted ? "default" : "outline"}
                >
                  Participation:{" "}
                  {participationGranted ? "granted" : "not granted"}
                </Badge>
                <Badge
                  data-testid="granted-public"
                  data-granted={publicGranted ? "true" : "false"}
                  variant={publicGranted ? "default" : "outline"}
                >
                  Public display: {publicGranted ? "granted" : "withheld"}
                </Badge>
              </div>
            </div>
          ) : (
            <form
              onSubmit={onSubmit}
              className="space-y-4"
              noValidate
              data-testid="consent-grant-form"
            >
              <fieldset className="space-y-3">
                <legend className="text-sm font-medium">Consent scopes</legend>
                <div className="flex items-start gap-3">
                  <input
                    id="scope-participation"
                    type="checkbox"
                    className="mt-1 size-4"
                    checked={participation}
                    disabled={pending}
                    onChange={(e) => setParticipation(e.target.checked)}
                    data-testid="consent-scope-participation"
                  />
                  <Label htmlFor="scope-participation" className="font-normal">
                    Participation — allow the competitor to progress past
                    pending review
                  </Label>
                </div>
                <div className="flex items-start gap-3">
                  <input
                    id="scope-public"
                    type="checkbox"
                    className="mt-1 size-4"
                    checked={publicDisplay}
                    disabled={pending}
                    onChange={(e) => setPublicDisplay(e.target.checked)}
                    data-testid="consent-scope-public"
                  />
                  <Label htmlFor="scope-public" className="font-normal">
                    Public display — show the competitor on the public portal
                    (optional; default off)
                  </Label>
                </div>
              </fieldset>

              <div className="space-y-2">
                <Label htmlFor="grantedBy">Your name (optional)</Label>
                <Input
                  id="grantedBy"
                  className="min-h-11"
                  value={grantedBy}
                  disabled={pending}
                  onChange={(e) => setGrantedBy(e.target.value)}
                  autoComplete="name"
                />
              </div>

              <ApiErrorAlert
                error={error}
                title={
                  error?.code === "CONSENT_TOKEN_INVALID"
                    ? "Invalid or expired token"
                    : "Could not grant consent"
                }
              />

              <Button
                type="submit"
                className="min-h-11 w-full"
                disabled={pending || (!participation && !publicDisplay)}
                data-testid="consent-grant-submit"
              >
                {pending ? "Saving…" : "Grant selected consent"}
              </Button>
            </form>
          )}
        </CardContent>
      </Card>
    </div>
  );
}
